function request(url, { cookie, referer, headers = {} } = {}) {
  return new Promise((resolve, reject) => {
    const u = new URL(url);
    const baseHeaders = {
      'accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
      'accept-language': 'en-US,en;q=0.9',
      'user-agent': UA,
      ...(cookie && { cookie }),
      ...(referer && { referer }),
      ...headers
    };

    let session;
    let settled = false;
    let status = null;
    let respHeaders = {};

    const finish = (st, headers_, body) => {
      if (settled) return;
      settled = true;
      try { session.close(); } catch (_) {}
      resolve({ status: st, headers: headers_, body, url });
    };

    try {
      session = http2.connect(u.origin, { settings: { maxHeaderListSize: 65536 } });
    } catch (e) {
      return reject(e);
    }

    const stream = session.request({
      ':method': 'GET',
      ':path': u.pathname + u.search,
      ':authority': u.hostname,
      ':scheme': u.protocol.replace(':', ''),
      ...baseHeaders
    });

    let body = '';
    stream.setEncoding('utf8');
    stream.on('response', (head) => {
      status = head[':status'];
      respHeaders = head;
    });
    stream.on('data', (c) => (body += c));
    stream.on('end', () => finish(status, respHeaders, body));
    stream.on('error', () => {
      if (!settled) {
        settled = true;
        try { session.close(); } catch (_) {}
        fallback1(url, { cookie, referer, headers }, resolve, reject);
      }
    });
    stream.end();
  });
}

function fallback1(url, opts, resolve, reject) {
  const u = new URL(url);
  const h = {
    'User-Agent': UA,
    'Accept-Language': 'en-US,en;q=0.9',
    ...(opts.cookie && { Cookie: opts.cookie }),
    ...(opts.referer && { Referer: opts.referer }),
    ...opts.headers
  };

  https
    .get({ hostname: u.hostname, path: u.pathname + u.search, headers: h }, (r) => {
      let d = '';
      r.on('data', (c) => (d += c));
      r.on('end', () => resolve({ status: r.statusCode, headers: r.headers, body: d, url }));
    })
    .on('error', reject);
}

function getSetCookies(headers) {
  const sc = headers['set-cookie'];
  if (!sc) return '';
  return sc
    .map((c) => c.split(';')[0])
    .filter(Boolean)
    .join('; ');
}

function isDoodUrl(url) {
  try {
    const host = new URL(url).hostname;
    return DOOD_HOSTS.some((d) => host === d || host.endsWith('.' + d));
  } catch {
    return false;
  }
}

function extractFilecode(url) {
  const m = String(url).match(/\/(?:d|e|f|v)\/([A-Za-z0-9]+)/);
  return m ? m[1] : (String(url).split('/').filter(Boolean).pop() || null);
}

function embedUrlFor(url) {
  const fc = extractFilecode(url);
  if (!fc) return null;
  const u = new URL(url);
  return `${u.protocol}//${u.hostname}/e/${fc}`;
}

function parsePlayer(html) {
  const titleMatch = html.match(/<title>\s*([^<]*?)\s*-\s*DoodStream/i) || html.match(/<title>\s*([^<]*?)\s*<\/title>/i);
  const title = titleMatch ? titleMatch[1].trim() : '';

  const thumb = (html.match(/og:image.*?content="([^"]+)"/) || html.match(/name=['"]og:image['"]\s*content="([^"]+)"/) || [])[1] || null;
  const fileId = (html.match(/file_id',\s*'(\d+)'/) || html.match(/file_id",\s*"(\d+)"/) || [])[1] || null;
  const aff = (html.match(/'aff',\s*'(\d+)'/) || html.match(/"aff",\s*"(\d+)"/) || [])[1] || null;

  const m = html.match(/['"`]\/pass_md5\/([A-Za-z0-9_\-/]+(?:\/[A-Za-z0-9_\-]+)?)/);
  if (m) {
    const parts = m[1].split('/');
    return { title, thumbnail: thumb, fileId, aff, md5id: parts[0], token: parts[1] || null };
  }

  const m2 = html.match(/\/pass_md5\/([A-Za-z0-9_\-]+)/);
  const tok = html.match(/["']token["']\s*[:=]\s*["']([^"']+)["']/) || html.match(/&token=([A-Za-z0-9_\-]+)/);

  return {
    title,
    thumbnail: thumb,
    fileId,
    aff,
    md5id: m2 ? m2[1] : null,
    token: tok ? tok[1] : null
  };
}

function buildDownloadUrl(mp4, token) {
  return token ? `${mp4}?token=${encodeURIComponent(token)}&expiry=${Date.now()}` : mp4;
}

function parseMp4Duration(buf) {
  let off = 0;
  while (off + 8 <= buf.length) {
    const size = buf.readUInt32BE(off);
    const typ = buf.toString('latin1', off + 4, off + 8);

    if (typ === 'moov') {
      off += 8;
      continue;
    }

    if (typ === 'mvhd') {
      const version = buf[off + 8];
      let p = off + 12;
      if (version === 1) {
        p += 16;
        if (p + 16 > buf.length) return null;
        const ts = Number(buf.readBigUInt64BE(p));
        const dur = Number(buf.readBigUInt64BE(p + 8));
        return dur && ts ? dur / ts : null;
      }
      p += 8;
      if (p + 8 > buf.length) return null;
      const ts = buf.readUInt32BE(p);
      const dur = buf.readUInt32BE(p + 4);
      return dur && ts ? dur / ts : null;
    }

    if (size < 8 || off + size > buf.length) return null;
    off += size;
  }
  return null;
}

function formatTime(sec) {
  const s = Math.round(sec);
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const ss = s % 60;
  const pad = (n) => String(n).padStart(2, '0');
  return h > 0 ? `${h}:${pad(m)}:${pad(ss)}` : `${m}:${pad(ss)}`;
}

function formatBytes(b) {
  const u = ['B', 'KB', 'MB', 'GB', 'TB'];
  let i = 0;
  let v = b;
  while (v >= 1024 && i < u.length - 1) {
    v /= 1024;
    i++;
  }
  return `${v.toFixed(1)} ${u[i]}`;
}

function probeMeta(downloadUrl, referer) {
  return new Promise((resolve) => {
    let remaining = 5;

    const run = (u) => {
      let target;
      try { target = new URL(u); } catch { return resolve(null); }

      const req = https.request(
        {
          hostname: target.hostname,
          path: target.pathname + target.search,
          headers: {
            'user-agent': UA,
            referer: referer || '',
            range: 'bytes=0-8191'
          }
        },
        (res) => {
          if (res.statusCode >= 300 && res.statusCode < 400) {
            res.resume();
            const loc = res.headers.location;
            if (!loc || --remaining <= 0) return resolve(null);
            return run(new URL(loc, u).toString());
          }

          if (res.statusCode !== 206 && res.statusCode !== 200) {
            res.resume();
            return resolve(null);
          }

          let size = null;
          const cr = res.headers['content-range'];
          if (cr) {
            const m = cr.match(/\/(\d+)$/);
            if (m) size = parseInt(m[1], 10);
          } else if (res.headers['content-length']) {
            size = parseInt(res.headers['content-length'], 10);
          }

          const chunks = [];
          res.on('data', (c) => chunks.push(c));
          res.on('error', () => resolve(null));
          res.on('end', () => {
            const buf = Buffer.concat(chunks);
            resolve({ size, duration: parseMp4Duration(buf) });
          });
        }
      );

      req.on('error', () => resolve(null));
      req.end();
    };

    run(downloadUrl);
  });
}

function safeName(s) {
  const n = String(s || '')
    .replace(/[^\w\- ]+/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  return n || 'video';
}

function downloadFile(url, outPath, { referer } = {}) {
  return new Promise((resolve, reject) => {
    let remaining = 5;

    const run = (u) => {
      let target;
      try { target = new URL(u); } catch (e) { return reject(e); }

      const mod = target.protocol === 'https:' ? https : http;
      const headers = { 'User-Agent': UA };
      if (referer) headers.Referer = referer;

      const req = mod.request(
        {
          hostname: target.hostname,
          port: target.port || undefined,
          path: target.pathname + target.search,
          headers
        },
        (res) => {
          if (res.statusCode >= 300 && res.statusCode < 400) {
            res.resume();
            const loc = res.headers.location;
            if (!loc || --remaining <= 0) return reject(new Error('Terlalu banyak redirect saat download'));
            return run(new URL(loc, u).toString());
          }

          if (res.statusCode !== 200) {
            res.resume();
            return reject(new Error(`HTTP ${res.statusCode} saat download`));
          }

          const ws = fs.createWriteStream(outPath);
          let bytes = 0;
          let lastPrint = 0;

          res.on('data', (c) => {
            bytes += c.length;
            const t = Date.now();
            if (t - lastPrint > 500) {
              lastPrint = t;
              process.stderr.write(`\r${(bytes / 1048576).toFixed(1)} MB`);
            }
          });

          res.pipe(ws);
          ws.on('error', reject);
          ws.on('close', () => {
            process.stderr.write('\n');
            resolve({ file: outPath, bytes });
          });
        }
      );

      req.on('error', reject);
      req.end();
    };

    run(url);
  });
}

async function scrapeDood(inputUrl) {
  if (!isDoodUrl(inputUrl)) {
    throw new Error('URL bukan milik domain Dood/DoodStream yang didukung.');
  }

  let embed;
  if (/\/e\/[A-Za-z0-9]+$/.test(inputUrl)) {
    embed = inputUrl;
  } else {
    try {
      const r = await request(inputUrl, { referer: new URL(inputUrl).origin });
      const finalUrl = new URL(r.url);
      embed = finalUrl.pathname.startsWith('/e/')
        ? r.url
        : `${finalUrl.protocol}//${finalUrl.hostname}/e/${extractFilecode(inputUrl)}`;
    } catch (_) {
      embed = embedUrlFor(inputUrl);
    }
  }

  if (!embed) throw new Error('Tidak bisa menentukan halaman embed (/e/)');

  const page = await request(embed, { referer: new URL(embed).origin });
  if (page.status !== 200) throw new Error(`Page embed HTTP ${page.status}`);
  if (!/pass_md5/.test(page.body)) {
    throw new Error('pass_md5 tidak ditemukan (file tidak valid / private / terhapus)');
  }

  const cookie = getSetCookies(page.headers);
  const { title, thumbnail, fileId, aff, md5id, token } = parsePlayer(page.body);
  if (!md5id) throw new Error('md5id tidak ditemukan di halaman player');

  const origin = new URL(embed).origin;
  const passPath = token ? `/pass_md5/${md5id}/${token}` : `/pass_md5/${md5id}`;
  const pass = await request(origin + passPath, {
    cookie,
    referer: embed,
    headers: {
      'accept': 'application/json, text/javascript, */*; q=0.01',
      'x-requested-with': 'XMLHttpRequest'
    }
  });

  const mp4 = pass.body.trim();
  if (!/^https?:\/\//.test(mp4)) {
    throw new Error(`pass_md5 tidak mengembalikan URL mp4 (HTTP ${pass.status}): ${mp4.slice(0, 120)}`);
  }

  const downloadUrl = buildDownloadUrl(mp4, token || '');
  const meta = await probeMeta(downloadUrl, embed);

  return {
    title,
    filecode: extractFilecode(inputUrl) || md5id,
    fileId,
    thumbnail,
    duration: meta && meta.duration ? formatTime(meta.duration) : null,
    durationSec: meta && meta.duration ? Math.round(meta.duration) : null,
    fileSize: meta && meta.size ? meta.size : null,
    fileSizeHuman: meta && meta.size ? formatBytes(meta.size) : null,
    aff,
    source: embed,
    downloadUrl
  };
}

async function main() {
  const args = process.argv.slice(2);
  let download = false;
  let output = null;
  let input = null;

  for (let i = 0; i < args.length; i++) {
    const a = args[i];
    if (a === '--download' || a === '-d') download = true;
    else if (a === '--output' || a === '-o') output = args[++i];
    else if (a.startsWith('-o=')) output = a.slice(3);
    else if (a.startsWith('--output=')) output = a.slice(9);
    else input = a;
  }

  if (!input && !process.stdin.isTTY) {
    input = fs.readFileSync(0, 'utf8').trim();
  }

  if (!input) {
    console.error('Pemakaian: node dood.js [--download|-d] [-o <file.mp4>] "<url>"');
    process.exit(1);
  }

  try {
    const data = await scrapeDood(input);
    if (!download) {
      console.log(JSON.stringify(data, null, 2));
      return;
    }
    const target = output || path.join(process.cwd(), `${safeName(data.title)}.mp4`);
    console.error(`Mengunduh ke ${target} ...`);
    const dl = await downloadFile(data.downloadUrl, target, { referer: data.source });
    console.error(`Selesai: ${(dl.bytes / 1048576).toFixed(1)} MB -> ${dl.file}`);
  } catch (e) {
    console.error('Gagal:', e.message);
    process.exit(1);
  }
}

if (require.main === module) main();

